import { ValidatedNEA } from "../Validated";
import { ValidatorNEA } from "./Types";
import { ArrayError } from "../ValidationErrors";
/**
 * Validates an array of values using the validator provided on
 * each item. If any one validator fails validation, the
 * array passed in will fail validation with errors describing
 * the failed elements.
 *
 * @param validator The validator to apply to each item in the array.
 *
 * @internal
 */
export declare const forEach: <E, T, U>(validator: ValidatorNEA<E, T, U>) => (array: T[]) => ValidatedNEA<ArrayError, U[]>;
